import { hideChartPopover, showChartPopover } from "../chart-board/board-util";

const generateTreemapTooltip = (datum, config) => {
	let key = "id";
	let val = "value";
	if (config.identity) {
		key = config.identity;
	}
	if (config.value) {
		val = config.value;
	}
	return typeof config?.itemTooltip === "function"
		? config.itemTooltip(datum)
		: `<div class="--hbr-treemap-popover-entity">
    <svg class="--hbr-treemap-popover-color" style="background:${
			datum.color
		}; opacity: ${datum.opacity}"></svg>
    ${datum.data[key]}: ${datum.formattedValue || datum.data[val]}
  </div>`;
};

const showTreemapTooltip = (data, event, tooltipRef, config) => {
	if (event.target) {
		showChartPopover(tooltipRef, data, event, config?.itemTooltip, () =>
			generateTreemapTooltip(data, config),
		);
	}
};
const hideTreemapTooltip = (tooltipRef) => {
	hideChartPopover(tooltipRef);
};

export { showTreemapTooltip, hideTreemapTooltip };
